import os
import time
import logging
from urllib3.exceptions import MaxRetryError
from moler.device import DeviceFactory
from taf.rfrl.bts.connections import device_aliases as connection_names
from taf.rfrl.utilities.robot.general import get_builtin_value
from taf.rfrl.utilities.tl_config import (load_moler_configuration_from_tl, get_bts_instance_id,
                                          get_web_credentials_for_du)
from taf.selenium.gnb.oam.coam.classical import classical as selenium_coam


def login_to_webem_and_verify_responsiveness(sessions_number=1, max_login_time=25.0, gnb_id=0, du_id=0):
    """
    Create webem sessions and verify response time after login is up to max_login_time seconds.
    Then perform easy operations via gui to test webem responsiveness.
    :param sessions_number: number of created sessions
    :param max_login_time: max time in seconds between login to webem and application responsiveness.
    :param gnb_id: int, BTS id - related to Test Line configuration
    :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
    :return: None
    """
    raise_exception = False
    sessions = []
    failed_session_tests = {}
    if sessions_number > 1:
        established_sessions, session = _get_established_webem_sessions(gnb_id=gnb_id, du_id=du_id)
        established_sessions_number = len(established_sessions)
        if established_sessions_number <= sessions_number:
            sessions_to_create = sessions_number - established_sessions_number
            sessions.append(session)
        else:
            raise WrongNumberOfSessions("Unable to verify WebEM responsiveness due to "
                                        "too many already established sessions: {}".format(established_sessions))
    else:
        sessions_to_create = sessions_number

    for i in range(sessions_to_create):
        gui_obj = _create_webem_session(gnb_id=gnb_id, du_id=du_id, session_nr=i)
        sessions.append(gui_obj)
        try:
            start_time = time.time()
            bts_info = gui_obj.get_bts_start_up_view_info()
            stop_time = time.time()
            logging.info(bts_info)
            webem_availability_time_delta = stop_time - start_time
            logging.info("Time delta: {}s".format(webem_availability_time_delta))
            if webem_availability_time_delta > max_login_time:
                logging.error("Session{}: Webem not available after {}s from login. "
                              "Time delta: {}".format(i, max_login_time, webem_availability_time_delta))
                raise_exception = True
        except Exception as e:
            failed_session_tests["session{}".format(i)] = e
            logging.error("Failed to check response time for session{}: {}".format(i, e))

    _verify_sessions_established(sessions_number=sessions_number, session=sessions[-1], gnb_id=gnb_id, du_id=du_id)
    _verify_webem_responsiveness(session=sessions[-1], gnb_id=gnb_id, du_id=du_id)
    _verify_sessions_established(sessions_number=sessions_number, session=sessions[-1], gnb_id=gnb_id, du_id=du_id)

    _close_webem_sessions(sessions=sessions)

    if failed_session_tests:
        logging.error("Verification of sessions failed: {}".format(failed_session_tests))
        raise_exception = True

    if raise_exception:
        raise WebemVerificationError("Webem sessions verification failed")


@load_moler_configuration_from_tl()
def close_all_open_browsers(browser_type="chrome", gnb_id=0, du_id=0):
    """
    Close all windows of given browser type.
    :param browser_type: browser's process name e.g. chrome, firefox
    :param gnb_id: int, BTS id - related to Test Line configuration
    :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
    :return: None
    """
    gnb = DeviceFactory.get_device(format(connection_names.ssh_bts_du.format("GNB", gnb_id, du_id)))
    gnb.goto_state("UNIX_LOCAL")
    ps_cmd = gnb.get_cmd(cmd_name='ps',
                         cmd_params={
                             'options': '-ef'
                         })
    processes_to_kill = " ".join([str(process['PID']) for process in ps_cmd() if browser_type in process['CMD']])
    logging.debug("Kill {} processes: {}".format(browser_type, processes_to_kill))
    kill_cmd = gnb.get_cmd(cmd_name='kill',
                           cmd_params={'options': '-9', 'pid': processes_to_kill})

    sudo_kill = gnb.get_cmd(cmd_name='sudo',
                            cmd_params={
                                'cmd_object': kill_cmd
                            })
    sudo_kill()


def _create_webem_session(gnb_id, du_id, session_nr=0):
    credentials = get_web_credentials_for_du(gnb_id, du_id)
    gui_obj = selenium_coam()
    selenium_logs = os.path.join(get_builtin_value("OUTPUTDIR"), "session{}".format(session_nr), 'selenium_logs')
    download_folder = os.path.join(selenium_logs, "download")
    if not os.path.exists(download_folder):
        os.makedirs(download_folder)
    gui_obj.enable_virtual_display()
    gui_obj.login(url='https://{}/'.format(credentials['ip']),
                  username=credentials['username'],
                  password=credentials['password'],
                  browser="Chrome",
                  screenshot_dir=os.path.join(selenium_logs, 'screenshot'))
    return gui_obj


def _verify_webem_responsiveness(session, gnb_id, du_id):
    if not session.get_parameter_value(dist_name="MRBTS-{}".format(
            get_bts_instance_id(bts_id=gnb_id, du_id=du_id, bts_type="GNB")),
            filter_param="BTS name", abbr="btsName"):
        raise WebemVerificationError("Getting btsName value failed")
    if not session.get_active_alarm_info():
        raise WebemVerificationError("Getting active alarms failed")
    if not session.check_current_software_version(key="Active"):
        raise WebemVerificationError("Getting current SW version failed")


def _get_established_webem_sessions(gnb_id, du_id, session=None):
    if session is None:
        session = _create_webem_session(gnb_id=gnb_id, du_id=du_id, session_nr=-1)
    established_sessions = session.get_sessions_list_detail_info()
    webem_sessions_established = [established_session for established_session in established_sessions
                                  if established_session['Session type'] == 'EM']
    return webem_sessions_established, session


def _verify_sessions_established(sessions_number, session, gnb_id, du_id):
    webem_sessions_established, session = _get_established_webem_sessions(session=session, gnb_id=gnb_id, du_id=du_id)
    established_sessions_count = len(webem_sessions_established)
    if established_sessions_count == sessions_number:
        logging.info("{} WebEM sessions are established. Sessions list: {}".format(established_sessions_count,
                                                                                   webem_sessions_established))
    else:
        raise WrongNumberOfSessions("There should be {} WebEM sessions established but there is {} instead".format(
            sessions_number, established_sessions_count))


def _close_webem_sessions(sessions):
    for session in sessions:
        try:
            session.logout()
        except MaxRetryError as e:
            logging.warning(repr(e))
        finally:
            session.disable_virtual_display()


class WebemVerificationError(Exception):
    pass


class WrongNumberOfSessions(WebemVerificationError):
    pass
